  "postMealWalkingDesc": ": ಗ್ಲೂಕೋಸ್ ಹೆಚ್ಚಳವನ್ನು ಮಂದಗೊಳಿಸಲು ಮತ್ತು ಸೆಲ್ಯುಲಾರ್ ಒತ್ತಡವನ್ನು ಮಿತಿಗೊಳಿಸಲು ಊಟ/ರಾತ್ರಿಯ ಊಟದ ನಂತರ 15 ನಿಮಿಷಗಳ ನಡಿಗೆಯನ್ನು ತೆಗೆದುಕೊಳ್ಳಿ.",
  "pureWaterProtocol": "ಶುದ್ಧ ನೀರಿನ ಪ್ರೋಟೋಕಾಲ್",
  "pureWaterProtocolDesc": ": ಕೀಟನಾಶಕಗಳು ಮತ್ತು ಭಾರವಾದ ಲೋಹಗಳನ್ನು ತೊಡೆದುಹಾಕಲು ಡ್ಯುಯಲ್ ವಾಟರ್ ಫಿಲ್ಟರೇಶನ್ (RO + ಸಕ್ರಿಯ ಕಾರ್ಬನ್) ಬಳಸಿ. ಪ್ಲಾಸ್ಟಿಕ್ ನೀರಿನ ಬಾಟಲಿಗಳನ್ನು ತಪ್ಪಿಸಿ.",
  "immediateStressShield": "ತಕ್ಷಣದ ಒತ್ತಡ ಗುರಾಣಿ (ಮಿಯಾ AI)",
  "immediateStressShieldDesc": ": ನಿಮ್ಮ ನರಮಂಡಲವನ್ನು ಶಾಂತಗೊಳಿಸಲು ಪ್ರತಿದಿನ 4-7-8 ಉಸಿರಾಟ ಮತ್ತು 5-4-3-2-1 ಗ್ರೌಂಡಿಂಗ್ ವ್ಯಾಯಾಮಗಳನ್ನು ಬಳಸಿ.",
  "environmentalAudit": "ಪರಿಸರ ಆಡಿಟ್",
  "environmentalAuditDesc": ": ಪ್ಲಾಸ್ಟಿಕ್ ಕುಡಿಯುವ ಪಾತ್ರೆಗಳನ್ನು ನಿವಾರಿಸಿ (ಮೈಕ್ರೋಪ್ಲಾಸ್ಟಿಕ್‌ಗಳನ್ನು ತಡೆಯುತ್ತದೆ) ಮತ್ತು RO + ಸಕ್ರಿಯ ಕಾರ್ಬನ್ ಶೋಧನೆಯನ್ನು ಸ್ಥಾಪಿಸಿ.",
