  "gia.optNoPriorTesting": "ಕುಟುಂಬದಲ್ಲಿ ಯಾವುದೇ ಹಿಂದಿನ ಪರೀಕ್ಷೆಯಿಲ್ಲ",
  "gia.optTellMeBrca": "BRCA ಬಗ್ಗೆ ಇನ್ನಷ್ಟು ತಿಳಿಸಿ",
  "gia.optWhatIsLynch": "ಲಿಂಚ್ ಸಿಂಡ್ರೋಮ್ ಎಂದರೇನು?",
  "gia.optBookCounseling": "ಆನುವಂಶಿಕ ಸಮಾಲೋಚನೆ ಕಾಯ್ದಿರಿಸಿ",
  "gia.qCancerTypes": "ಧನ್ಯವಾದಗಳು. ತಲೆಮಾರುಗಳಾದ್ಯಂತ ಕ್ಯಾನ್ಸರ್ ವಿಧಗಳನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳುವುದು ಬಹಳ ಮುಖ್ಯ.\n\nನಿಮಗೆ ಅಥವಾ ನಿಮ್ಮ ಕುಟುಂಬಕ್ಕೆ ಯಾವ ರೀತಿಯ ಕ್ಯಾನ್ಸರ್ ಇರುವುದು ಕಂಡುಬಂದಿದೆ?",
  "gia.qAge": "ಧನ್ಯವಾದಗಳು. ರೋಗನಿರ್ಣಯದ ವಯಸ್ಸು ಆನುವಂಶಿಕ ಅಪಾಯದ ಪ್ರಮುಖ ಸೂಚಕವಾಗಿದೆ.\n\nಕ್ಯಾನ್ಸರ್ ಮೊದಲ ಬಾರಿಗೆ ಯಾವ ವಯಸ್ಸಿನಲ್ಲಿ ಪತ್ತೆಯಾಯಿತು?",
  "gia.qRelatives": "ಅರ್ಥವಾಯಿತು. ಯಾವ ನಿರ್ದಿಷ್ಟ ಸಂಬಂಧಿಕರು ಪ್ರಭಾವಿತರಾಗಿದ್ದಾರೆ ಮತ್ತು ಕುಟುಂಬದ ಯಾವ ಕಡೆಯಿಂದ?",
  "gia.qAncestry": "ತಿಳಿಯಿತು. ಕುಟುಂಬದಲ್ಲಿ ಯಾವುದೇ ಆನುವಂಶಿಕ ಪರೀಕ್ಷಾ ಫಲಿತಾಂಶಗಳಿವೆಯೇ (ಉದಾ: BRCA1/2 ಪಾಸಿಟಿವ್)?",
  "gia.assessmentSummary": "### 🧬 NCCN v2.2025 ಆಂಕೊಜೆನೆಟಿಕ್ ಅಪಾಯದ ಮೌಲ್ಯಮಾಪನ\n\nಹಂಚಿಕೊಂಡ ಇತಿಹಾಸದ ಆಧಾರದ ಮೇಲೆ, **ಆನುವಂಶಿಕ ಕ್ಯಾನ್ಸರ್ ಪರೀಕ್ಷೆಯನ್ನು ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ**.\n\n**ಮೌಲ್ಯಮಾಪನ ಮಾಡಬೇಕಾದ ಪ್ಯಾನೆಲ್‌ಗಳು:**\n- **HBOC ಪ್ಯಾನೆಲ್ (BRCA1, BRCA2, PALB2, ATM, CHEK2)**\n- **ಲಿಂಚ್ ಸಿಂಡ್ರೋಮ್ ಪ್ಯಾನೆಲ್ (MLH1, MSH2, MSH6, PMS2, EPCAM)**\n\n**ಮುಂದಿನ ಹಂತಗಳು:**\n1. ಪ್ರಮಾಣೀಕೃತ ಆನುವಂಶಿಕ ಸಲಹೆಗಾರರನ್ನು ಸಂಪರ್ಕಿಸಿ.\n2. ಬಹು-ಜೀನ್ ಪ್ಯಾನೆಲ್ ರಕ್ತ ಪರೀಕ್ಷೆಯನ್ನು ಮಾಡಿಸಿ.",
  "closeChatAria": "ಚಾಟ್ ಮುಚ್ಚಿ",
  "gia.assessmentNextStepsDesc": "ಆನುವಂಶಿಕ ಸಲಹೆಗಾರರು ನಿಮ್ಮ ವಂಶಾವಳಿಯನ್ನು ಪರಿಶೀಲಿಸಿ ಸೂಕ್ತ ಪರೀಕ್ಷೆಗಳನ್ನು ಶಿಫಾರಸು ಮಾಡುತ್ತಾರೆ.",
